brand_tokens_css:
:root {
  --brand-primary:   #E8521E;
  --brand-secondary: #1B3A8C;
  --brand-tertiary:  #0E1A3A;
  --brand-accent:    #0E1A3A;
  --brand-costume:   #FFFFFF;
  --ink:             #0E1A3A;
  --canvas:          #FFFFFF;
  --brand-gradient:  linear-gradient(135deg, #E8521E 0%, #1B3A8C 50%, #0E1A3A 100%);
  --deco-1:          #F7CB46;
  --deco-2:          #99E885;
  --deco-3:          #C0F7FE;
  --deco-4:          #FE90E8;
  --font-display:    'Anton', ui-monospace, monospace;
  --font-body:       'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --font-mono:       'Space Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --shadow-hard: 8px 8px 0 var(--ink);
  --shadow-hover: 11px 11px 0 var(--ink);
  --border-bold: 4px solid var(--ink);
  --border-loud: 6px solid var(--ink);
  --tilt-l: -1deg;
  --tilt-r: 1deg;
  --gap-loud: 1.7vw; /* ~32px on a 1920 canvas */
}
